"""Settings for the JSI protocol."""

import dataclasses

from jsilib import _utils

__all__ = export = _utils.ExportList()


@export
@dataclasses.dataclass
class Settings:
    """Settings for the JSI protocol.

    :attr chunk_size:
        Maximal size of single data chunk (in bytes)

    :attr ping_idle_time:
        Time to wait (in seconds) for another frame before PING is sent to
        check if the peer is still alive.

        In current implementation, PING-s are not sent during normal frame
        exchange between two communicating peers, but only if time elapsed
        between receiving frame N and frame N+1 exceeds this value. Thanks to
        this, peers are not spammed with PING requests when it is known that
        connection is in good health.

        To disable this feature completely, set this to a non-positive value
        (i.e. <= 0).

    :attr ping_retry_count:
        Number of PING request retries before saying that connection is lost.

        After *ping_idle_time* of inactivity, first PING frame is sent. If it
        is not responded within *ping_idle_time*, then another one is sent
        (1st retry). If that another is not responded within *ping_idle_time^2*,
        then yet another one is sent (2nd retry) with time for response set to
        *ping_idle_time^3*. If number of retries exceeds *ping_retry_count*,
        then connection is said to be lost. Moreover, each received PONG frame
        is compared with last PING frame; if their ping ID-s do not match,
        the such PONG frame is treated as it was not received at all.
    """
    chunk_size: int = 65536
    ping_idle_time: float = 2.0
    ping_loss_threshold: int = 3
